public synchronized Optional<io.github.diodeme.ji.session.tree.SessionRunConfigurationSource.RunConfiguration>
        activeRunConfiguration(String sessionId) {
    return activeRunConfig(sessionId).map(config ->
            new io.github.diodeme.ji.session.tree.SessionRunConfigurationSource.RunConfiguration(
                    config.revision(), new ModelRef(config.profileId(), config.modelId()),
                    "default".equals(config.reasoning()) ? Map.of()
                            : Map.of("reasoning", config.reasoning())));
}

